#[gpui::test]
async fn test_subscription_leaks_handlers_after_server_drop(cx: &mut TestAppContext) {
    cx.update(|cx| {
        release_channel::init(semver::Version::new(0, 0, 0), cx);
    });
    let (server, mut fake) = FakeLanguageServer::new(
        LanguageServerId(0),
        LanguageServerBinary {
            path: "path/to/language-server".into(),
            arguments: vec![],
            env: None,
        },
        "the-lsp".to_string(),
        Default::default(),
        &mut cx.to_async(),
    );

    let detached_payload = Arc::new(());
    let detached_payload_handle = Arc::downgrade(&detached_payload);
    server
        .on_notification::<notification::ShowMessage, _>(move |_, _| {
            let _payload = &detached_payload;
        })
        .detach();

    let retained_payload = Arc::new(());
    let retained_payload_handle = Arc::downgrade(&retained_payload);
    let subscription =
        server.on_notification::<notification::PublishDiagnostics, _>(move |_, _| {
            let _payload = &retained_payload;
        });

    let server = cx
        .update(|cx| {
            let params = server.default_initialize_params(false, false, cx);
            let configuration = DidChangeConfigurationParams {
                settings: Default::default(),
            };
            server.initialize(
                params,
                configuration.into(),
                DEFAULT_LSP_REQUEST_TIMEOUT,
                cx,
            )
        })
        .await
        .unwrap();

    drop(server);
    cx.run_until_parked();
    fake.receive_notification::<notification::Exit>().await;
    drop(fake);
    cx.run_until_parked();

    assert!(
        detached_payload_handle.upgrade().is_none(),
        "detached handler was kept alive after the server was dropped, \
        because an unrelated retained subscription pins the whole handler map"

/// Language server protocol RPC request message ID.
///
/// [LSP Specification](https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#requestMessage)
#[derive(Debug, Clone, Eq, PartialEq, Hash, Serialize, Deserialize)]
#[serde(untagged)]
pub enum RequestId {
    Int(i32),
    Str(String),
}

fn is_unit<T: 'static>(_: &T) -> bool {
    TypeId::of::<T>() == TypeId::of::<()>()
}

fn deserialize_params<T: DeserializeOwned + 'static>(params: Value) -> serde_json::Result<T> {
    if TypeId::of::<T>() == TypeId::of::<()>() {
        serde_json::from_value(Value::Null)
    } else {
        serde_json::from_value(params)
    }
}

fn deserialize_result<T: DeserializeOwned + 'static>(result: &str) -> serde_json::Result<T> {
    if TypeId::of::<T>() == TypeId::of::<()>() {
        serde_json::from_str("null")
    } else {
        serde_json::from_str(result)
    }
}

/// Language server protocol RPC request message.
///
/// [LSP Specification](https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#requestMessage)
#[derive(Serialize, Deserialize)]
pub struct Request<'a, T>
where
    T: 'static,
{
    jsonrpc: &'static str,
    id: RequestId,
    method: &'a str,
    #[serde(default, skip_serializing_if = "is_unit")]
    params: T,
}

/// Language server protocol RPC request response message before it is deserialized into a concrete type.
#[derive(Serialize, Deserialize)]
struct AnyResponse<'a> {
    jsonrpc: &'a str,
    id: RequestId,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    error: Option<Error>,
    #[serde(borrow, skip_serializing_if = "Option::is_none")]
    result: Option<&'a RawValue>,
}

/// Language server protocol RPC request response message.
///
/// [LSP Specification](https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#responseMessage)
#[derive(Serialize)]
struct Response<T> {
    jsonrpc: &'static str,
    id: RequestId,
    #[serde(flatten)]
    value: LspResult<T>,
}

#[derive(Serialize)]
#[serde(rename_all = "snake_case")]
enum LspResult<T> {
    #[serde(rename = "result")]
    Ok(Option<T>),
    Error(Option<Error>),
}

/// Language server protocol RPC notification message.
///
/// [LSP Specification](https://microsoft.github.io/language-server-protocol/specifications/lsp/3.17/specification/#notificationMessage)
#[derive(Serialize, Deserialize)]
struct Notification<'a, T>
where
    T: 'static,
{
    jsonrpc: &'static str,
    #[serde(borrow)]
    method: &'a str,
    #[serde(default, skip_serializing_if = "is_unit")]
    params: T,
}

/// Language server RPC notification message before it is deserialized into a concrete type.
#[derive(Debug, Clone, Deserialize)]
struct NotificationOrRequest {
    #[serde(default)]
    id: Option<RequestId>,
    method: String,
    #[serde(default)]
    params: Option<Value>,
}

